import{c as t,Q as a,j as o,m as n}from"./chunks/framework.BqPkuuVc.js";const p=JSON.parse('{"title":"Reaching the server: name or IP","description":"","frontmatter":{},"headers":[],"relativePath":"user/reference/server-addresses.md","filePath":"user/reference/server-addresses.md"}'),r={name:"user/reference/server-addresses.md"};function s(i,e,h,d,l,c){return a(),o("div",null,[...e[0]||(e[0]=[n(`<h1 id="reaching-the-server-name-or-ip" tabindex="-1">Reaching the server: name or IP <a class="header-anchor" href="#reaching-the-server-name-or-ip" aria-label="Permalink to &quot;Reaching the server: name or IP&quot;">​</a></h1><p><strong>Audience:</strong> Event organisers setting up admin laptops, volunteer workstations, phones and TVs to reach the Manager server.</p><p><strong>Settings → Server</strong> lists two kinds of address for every app — Manager, Registration, Spectator, Kiosk, Info screens and Commentary — one built on the <strong>computer&#39;s name</strong>, one on its <strong>LAN IP</strong> (tagged <strong>IP</strong> in the table). Once <a href="./https-and-certificates">HTTPS</a> is on, each also has a secure version, tagged <strong>HTTPS</strong>. They reach the same server, but they are <em>not</em> interchangeable: which one works depends on the device and the browser. Handing the wrong one to a download laptop is the most common reason a volunteer reports &quot;I can&#39;t reach the server.&quot;</p><h2 id="the-short-version" tabindex="-1">The short version <a class="header-anchor" href="#the-short-version" aria-label="Permalink to &quot;The short version&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Device</th><th>Which link to use</th></tr></thead><tbody><tr><td>Phones, tablets, spectator TVs</td><td><strong>Name link</strong> — mobile devices find the computer&#39;s name on their own.</td></tr><tr><td>Admin laptops — card download, station backup, <a href="./../running-the-event/registration-desk">entry desk</a></td><td><strong>IP link.</strong> These usually run Chrome, and Chrome won&#39;t resolve a <code>.local</code> name.</td></tr><tr><td>The server computer itself</td><td>Neither — open <code>http://localhost:5154/manager</code> (or the <strong>HTTP port</strong> you set, if you changed it). See <a href="./https-and-certificates#do-you-even-need-https">HTTPS and certificates</a>.</td></tr></tbody></table><blockquote><p><strong>Rule of thumb:</strong> the name is for devices people carry; the IP is for laptops doing the work.</p></blockquote><h2 id="opening-a-link-on-a-phone-or-tablet" tabindex="-1">Opening a link on a phone or tablet <a class="header-anchor" href="#opening-a-link-on-a-phone-or-tablet" aria-label="Permalink to &quot;Opening a link on a phone or tablet&quot;">​</a></h2><p>Every link in the <strong>Access links</strong> table has a QR code button beside its copy button. Press it and the link is shown as a QR code — point the phone&#39;s or tablet&#39;s camera at the screen and it opens the link, with nothing to type. Show the code for the link that suits the device, as in the table above: the name link for a phone, the IP link for a device that cannot find the name.</p><h2 id="why-the-name-doesn-t-always-work" tabindex="-1">Why the name doesn&#39;t always work <a class="header-anchor" href="#why-the-name-doesn-t-always-work" aria-label="Permalink to &quot;Why the name doesn&#39;t always work&quot;">​</a></h2><p>The name link is usually the computer&#39;s name with <code>.local</code> on the end, such as <code>mesho.local</code>. (If your router gives the computer a name of its own, such as <code>mesho.lan</code>, the link uses that instead — see <a href="#giving-the-laptops-a-name-that-works">Giving the laptops a name that works</a>.) A <code>.local</code> name isn&#39;t resolved by ordinary DNS. No server anywhere holds a record for it — instead the computer answers a <strong>multicast query</strong> on the local network, a mechanism called mDNS (Apple calls it Bonjour). That&#39;s why it needs no configuration at all: it works the moment both devices are on the same network.</p><p>The catch is that each device decides for itself whether to ask that way.</p><ul><li><p><strong>iOS, iPadOS, Android and macOS</strong> (Safari, and every other Mac app that asks the system) do mDNS natively. Phones, tablets and TVs resolve the name without you doing anything — which is exactly the audience the name link is good for. Windows 10 and later, and most Linux desktops, usually manage it too.</p></li><li><p><strong>Firefox</strong> asks the operating system rather than resolving names itself, so it inherits whatever the machine can do — on a Mac or a phone, that means the name works.</p></li><li><p><strong>Chrome ships its own DNS resolver</strong> and, in practice, won&#39;t resolve a <code>.local</code> name — treat it as never working. It sends the lookup to your router as an ordinary DNS query, no router ever holds a <code>.local</code> name, and Chrome reports:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>This site can&#39;t be reached</span></span>
<span class="line"><span>DNS_PROBE_FINISHED_NXDOMAIN</span></span></code></pre></div><p>The same machine will usually load the same address perfectly in Safari, which is a good way to confirm this is what you&#39;re hitting.</p></li></ul><p>There is no Chrome setting that fixes it. Turning off <strong>Secure DNS</strong>, granting it local network access, clearing its host cache and the <code>BuiltInDnsClientEnabled</code> policy have all been tried, and none of them helped. Nothing in Manager can fix it either: the name it publishes is right, and the rest of the network finds it. Don&#39;t spend time renaming the computer to work around it — see the warning under <a href="#giving-the-laptops-a-name-that-works">Giving the laptops a name that works</a>.</p><blockquote><p><strong>This lands hardest exactly where it hurts.</strong> Reading SportIdent cards in the browser needs the Web Serial API, which is supported by <strong>Chrome, Edge and Firefox 151+</strong> — see <a href="./../running-the-event/card-download">Downloading cards</a>. In practice download and station-backup laptops run Chrome, the one browser least likely to resolve the name. <strong>Give those machines the IP link.</strong> Firefox 151+ can read cards too and asks the operating system for names, so it should manage the name link — but that hasn&#39;t been tried at an event yet, and the IP link works everywhere. It stays the safe default.</p></blockquote><h2 id="giving-the-laptops-a-name-that-works" tabindex="-1">Giving the laptops a name that works <a class="header-anchor" href="#giving-the-laptops-a-name-that-works" aria-label="Permalink to &quot;Giving the laptops a name that works&quot;">​</a></h2><p>If you&#39;d rather not hand out IP addresses — they&#39;re easy to mistype and they can change — have your <strong>router</strong> serve the name instead. A router-served name is ordinary DNS, so every browser resolves it, Chrome included.</p><p>Most home and event routers do this from one screen:</p><ol><li>Note the server&#39;s current address from <strong>Settings → Server</strong> (shown as <strong>LAN IP</strong> under the computer name).</li><li>In the router&#39;s admin page, find <strong>DHCP reservations</strong> (sometimes &quot;static leases&quot; or &quot;address reservation&quot;) and add one for the server.</li><li>Give the reservation a <strong>host name</strong> — <code>mesho</code> is a good choice.</li><li>Save, then restart the server so it picks up the new address.</li></ol><p>Devices then reach it at that name plus whatever local domain your router uses — commonly <code>mesho.lan</code>, <code>mesho.home</code>, or <code>mesho.localdomain</code>. Manager notices the change and the <strong>Access links</strong> table starts offering the new name on its own; you don&#39;t have to configure it anywhere in Manager.</p><p>This also pins the IP, which solves the next problem for free.</p><blockquote><p><strong>It has to be the router that&#39;s changed, not the computer.</strong> Renaming the server computer to something like <code>mesho.localdomain</code> looks like the same idea and doesn&#39;t work: it only changes what that machine calls itself, and no device on the network gains any way to look the name up. The address may still open on the server itself, which makes it seem fixed when it isn&#39;t — test from a second device before trusting it. The router is the thing that has to answer.</p></blockquote><h2 id="when-the-ip-changes" tabindex="-1">When the IP changes <a class="header-anchor" href="#when-the-ip-changes" aria-label="Permalink to &quot;When the IP changes&quot;">​</a></h2><p>Without a reservation, the server&#39;s address comes from DHCP and can differ from one event to the next — the links volunteers bookmarked last month may point nowhere. Two things worth knowing:</p><ul><li><strong>A DHCP reservation stops it changing.</strong> Worth doing once for a machine that&#39;s regularly the server.</li><li><strong>A new IP doesn&#39;t mean redoing certificates.</strong> If you use HTTPS, Manager reissues the server certificate itself and the CA your devices already trust still covers it — you just restart the server. See <a href="./https-and-certificates#if-the-server-is-renamed-or-its-ip-changes">If the server is renamed or its IP changes</a>.</li></ul><h2 id="troubleshooting" tabindex="-1">Troubleshooting <a class="header-anchor" href="#troubleshooting" aria-label="Permalink to &quot;Troubleshooting&quot;">​</a></h2><table tabindex="0"><thead><tr><th>What you see</th><th>What it means</th><th>What to do</th></tr></thead><tbody><tr><td><code>DNS_PROBE_FINISHED_NXDOMAIN</code> in Chrome</td><td>Chrome won&#39;t resolve the mDNS name</td><td>Use the <strong>IP</strong> link from the Access links table, or set up a router host name (above)</td></tr><tr><td>The name works in Safari or Firefox but not Chrome on the <em>same</em> laptop</td><td>Same cause — confirms it&#39;s the browser, not the network</td><td>As above</td></tr><tr><td>No link works from another device, name or IP</td><td>Network access is off, or a firewall is blocking</td><td>Check <strong>Allow access from other devices on the network</strong> in <strong>Settings → Server</strong>, then the server&#39;s firewall</td></tr><tr><td>The IP link loads but shows a certificate warning</td><td>Normal until the device trusts meshO&#39;s CA</td><td><a href="./https-and-certificates#trusting-the-certificate">Trusting the certificate</a></td></tr><tr><td>Card download controls don&#39;t appear, even though the page loads</td><td>Not an addressing problem — Web Serial needs Chrome, Edge or Firefox 151+ <strong>and</strong> a secure context</td><td><a href="./https-and-certificates#do-you-even-need-https">Do you even need HTTPS?</a></td></tr></tbody></table><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="./multi-operator-setup">Multi-operator setup</a> — the wider picture of running several workstations at one event</li><li><a href="./https-and-certificates">HTTPS and certificates</a> — needed when a download or backup workstation isn&#39;t the server</li><li><a href="./../running-the-event/card-download">Downloading cards</a> — which browsers can read a card reader</li><li><a href="./settings">Settings</a></li><li><a href="./troubleshooting">Troubleshooting</a></li></ul>`,28)])])}const m=t(r,[["render",s]]);export{p as __pageData,m as default};
